(()=>{
  const decoded=decodeURIComponent(location.pathname);
  const FILES={1:'01_이웃가게_발견.html',2:'02_이웃가게_상세.html',3:'03_주민혜택_쿠폰.html',4:'04_데일리홈.html',5:'05_우리단지_첫화면.html',6:'06_단지온공지_목록.html',7:'07_단지온공지_상세.html',8:'08_아파트소식_목록.html',9:'09_회장인사_상세.html',10:'10_주민소식_목록.html',11:'11_주민소식_상세.html',12:'12_이웃대화_첫화면.html',13:'13_이웃대화_글상세_댓글.html',14:'14_가입인사_글쓰기.html',15:'15_단지이야기_글쓰기.html',16:'16_궁금해요_글쓰기.html',17:'17_같이해요_글쓰기.html',18:'18_공통앱셸.html',19:'19_내정보_메인.html',20:'20_메시지함_목록.html',21:'21_메시지_대화상세.html',22:'22_주민_공개프로필.html',23:'23_이웃온기.html',24:'24_설정.html',25:'25_1대1문의.html',26:'26_우리집연결.html',27:'27_알림함.html',28:'28_나의활동.html',29:'index.html'};
  const route=number=>FILES[number]||'';
  const TOP={'홈':4,'이웃가게':1,'우리단지':5,'내정보':19};
  const FALLBACK={1:4,2:1,3:4,4:29,5:4,6:5,7:6,8:5,9:8,10:5,11:10,12:5,13:12,14:12,15:12,16:12,17:12,19:4,20:19,21:20,22:19,23:19,24:19,25:19,26:19,27:19,28:19,29:4};
  const pageNumber=()=>{const file=(decoded.split('/').pop()||'').split('?')[0];if(file==='index.html'||file==='')return 29;const m=file.match(/^(\d{2})(?:A)?_/);return m?Number(m[1]):0};
  const clean=value=>(value||'').replace(/\s+/g,' ').trim();
  const setRoute=(node,target)=>{if(!node||!target)return;node.dataset.route=target;node.removeAttribute('data-demo');node.removeAttribute('data-toast');node.removeAttribute('onclick');if(node.tagName==='A')node.href=target};
  const controls=()=>[...document.querySelectorAll('button,a,[role="button"]')];
  const withText=(pattern,target,scope=document)=>[...scope.querySelectorAll('button,a,[role="button"]')].forEach(node=>{if(pattern.test(clean(node.textContent)))setRoute(node,target)});
  const replaceText=(from,to,scope=document.body)=>{const walker=document.createTreeWalker(scope,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{if(node.nodeValue.includes(from))node.nodeValue=node.nodeValue.split(from).join(to)})};
  const rewriteLinks=()=>document.querySelectorAll('[href],[data-route]').forEach(node=>['href','data-route'].forEach(attr=>{const value=node.getAttribute(attr);if(!value)return;const match=decodeURIComponent(value).match(/(?:\.\.\/)+(\d{2})(?:-2)?_/);if(match&&FILES[Number(match[1])])node.setAttribute(attr,route(Number(match[1])))}));
  const normalizeCopy=()=>[['시연용 쿠폰 화면','주민 혜택 쿠폰'],['기존 승인 이미지로 구성한 시연 예시','주민이 함께 준비한 재능나눔 모임'],['디자인 검토용 화면으로 실제 접수·메일 전송은 되지 않습니다.','제보 내용은 운영진 확인 후 주민소식에 게시됩니다.'],['이 페이지는 목록 디자인만 다룹니다.','필요한 대화를 골라 내용을 확인하세요.'],['대화 상세와 답장 화면은 다음 한 페이지로 별도 제작합니다.','대화를 누르면 이전 메시지를 확인하고 답장할 수 있습니다.']].forEach(([a,b])=>replaceText(a,b));
  const removeAll=selector=>document.querySelectorAll(selector).forEach(node=>node.remove());
  const removeTextBlocks=(pattern,selector='p,section,article,aside,div')=>[...document.querySelectorAll(selector)].filter(node=>pattern.test(clean(node.textContent))&&!node.querySelector('h1')).forEach(node=>node.remove());
  const simpleBack=(label,target)=>{if(document.querySelector('.danjion-simple-back'))return;const main=document.querySelector('main');if(!main)return;const bar=document.createElement('div');bar.className='danjion-simple-back';bar.innerHTML='<button type="button">← '+label+'</button>';setRoute(bar.querySelector('button'),target);main.prepend(bar)};
  const writerPrefix=number=>{removeAll('.intro p,.intro .writer');const label={14:'가입인사',15:'단지이야기 · 단지 일상',16:'궁금해요 · 생활·살림',17:'같이해요 · 산책·운동'}[number];const head=document.querySelector('.form-head');if(head&&!head.querySelector('.danjion-prefix'))head.insertAdjacentHTML('afterend','<div class="danjion-prefix">말머리 <b>'+label+'</b></div>');document.querySelectorAll('[data-story-type],[data-question-type],[data-together-type],.story-type,.question-type,.together-type').forEach(button=>button.addEventListener('click',()=>{const badge=document.querySelector('.danjion-prefix b');if(badge)badge.textContent=({14:'가입인사',15:'단지이야기',16:'궁금해요',17:'같이해요'}[number]+' · '+clean(button.textContent))}))};
  const inquiryMode=()=>{replaceText('이웃가게·혜택','혜택 이용');const type=new URLSearchParams(location.search).get('type');if(!type)return;const spec=type==='shop-report'?{title:'이웃가게 제보',eyebrow:'NEIGHBOR SHOP REPORT',category:'가게 정보 제보',hint:'알리고 싶은 가게와 주민에게 도움이 될 정보를 적어주세요.'}:{title:'내 가게 등록 신청',eyebrow:'RESIDENT SHOP APPLICATION',category:'주민 가게 등록',hint:'가게 이름·업종·운영 정보를 적어주세요. 확인 후 등록 절차를 안내합니다.'};removeAll('.page-copy');const h1=document.querySelector('h1');if(h1)h1.textContent=spec.title;const eye=document.querySelector('.eyebrow');if(eye)eye.textContent=spec.eyebrow;const categories=document.querySelector('.categories');if(categories){const label=categories.previousElementSibling;if(label&&label.classList.contains('label-row'))label.remove();categories.innerHTML='<div class="danjion-selected-type"><span>접수 유형</span><b>'+spec.category+'</b></div>'}const textarea=document.querySelector('textarea');if(textarea)textarea.placeholder=spec.hint;const submit=document.querySelector('.submit');if(submit)submit.textContent=spec.title+' 접수하기'};
  const addBack=number=>controls().forEach(node=>{const label=clean(node.textContent),aria=node.getAttribute('aria-label')||'';if(node.matches('[data-back],.back-button,.back-btn,.back,.route>a:first-child,.route>button:first-child')||/^(←|‹)|뒤로|돌아가기/.test(label+' '+aria)){node.dataset.back='';node.dataset.fallback=route(FALLBACK[number]||4);node.removeAttribute('data-demo');node.removeAttribute('data-toast');node.removeAttribute('href');node.removeAttribute('onclick')}});
  const storeTools=()=>{withText(/^1:1 문의하기$/,'#storeInquiry');withText(/^위치 보기$/,'#storeLocation');document.querySelectorAll('[data-route="#storeLocation"]').forEach(node=>node.dataset.storeLocation='');document.querySelectorAll('[data-route="#storeInquiry"]').forEach(node=>node.dataset.storeInquiry='');const map=document.querySelector('.map-card');if(map){map.id='storeLocation';map.dataset.storeLocation='';map.removeAttribute('data-toast');map.removeAttribute('data-demo')}};
  const storeReviews=()=>{const tabs=document.querySelector('.section-tabs');if(!tabs||tabs.querySelector('[data-tab="reviews"]'))return;const tab=document.createElement('button');tab.type='button';tab.dataset.tab='reviews';tab.textContent='가게 후기 3';tabs.append(tab);const panel=document.createElement('section');panel.className='content-panel danjion-review-panel';panel.id='reviews';panel.setAttribute('aria-label','가게 후기');panel.innerHTML='<div class="danjion-review-head"><div><small>RESIDENT REVIEWS</small><h2>이웃의 가게 후기</h2><p>실제로 이용한 주민의 경험을 확인하세요.</p></div><button type="button" class="danjion-review-write">후기 쓰기</button></div><article class="danjion-review"><header><b>연블리 · 방림명지로드힐 주민</b><span>5점 · 2026.08.30</span></header><p>부모님 생신 꽃다발을 정성스럽게 준비해 주셨어요. 상담도 편안했습니다.</p></article><article class="danjion-review"><header><b>산책메이트 · 방림명지로드힐 주민</b><span>5점 · 2026.08.24</span></header><p>원하는 분위기를 잘 들어주시고 예약 시간에 맞춰 준비해 주셨어요.</p></article>';document.querySelector('#news')?.after(panel);tab.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(item=>item.classList.toggle('active',item===tab));document.querySelectorAll('.content-panel').forEach(item=>item.classList.toggle('active',item===panel))});const write=panel.querySelector('.danjion-review-write');write.addEventListener('click',()=>{let dialog=document.querySelector('#storeReviewDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='storeReviewDialog';dialog.className='danjion-store-dialog danjion-review-dialog';dialog.innerHTML='<form method="dialog"><header><button value="cancel" aria-label="후기 닫기">←</button><b>로드힐 꽃작업실 후기</b></header><label>평점<select aria-label="가게 평점"><option>5점</option><option>4점</option><option>3점</option><option>2점</option><option>1점</option></select></label><label>이용 후기<textarea aria-label="가게 후기 내용" placeholder="이용하며 좋았던 점을 적어주세요."></textarea></label><div><button value="cancel">취소</button><button class="primary" value="send">후기 등록</button></div></form>';document.body.append(dialog);dialog.addEventListener('close',()=>{if(dialog.returnValue!=='send')return;const review=document.createElement('article');review.className='danjion-review';review.innerHTML='<header><b>연블리 · 방림명지로드힐 주민</b><span>'+dialog.querySelector('select').value+' · 오늘</span></header><p>'+(dialog.querySelector('textarea').value.trim()||'정성스러운 응대가 좋았습니다.')+'</p>';panel.querySelector('.danjion-review-head').after(review);tab.textContent='가게 후기 4'})}dialog.showModal()});setRoute(panel.querySelector('.danjion-my-reviews'),route(28))};
  const openStoreInquiry=()=>{let dialog=document.querySelector('#storeInquiryDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='storeInquiryDialog';dialog.className='danjion-store-dialog';dialog.innerHTML='<form method="dialog"><header><button value="cancel" aria-label="문의 닫기">←</button><b>로드힐 꽃작업실에 문의</b></header><p>가게 운영자에게 보낼 내용을 적어주세요.</p><textarea aria-label="가게 문의 내용" placeholder="예약 가능 시간이나 상품을 문의해 보세요."></textarea><div><button value="cancel">취소</button><button class="primary" value="send">문의 보내기</button></div></form>';document.body.append(dialog);dialog.addEventListener('close',()=>{if(dialog.returnValue==='send'){const toast=document.querySelector('.toast');if(toast){toast.textContent='가게 문의를 보냈습니다.';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}}})}dialog.showModal()};
  const pageRoutes=number=>{
    if(number===1){simpleBack('홈',route(4));const intro=document.querySelector('.intro-note');if(intro)intro.innerHTML='<div class="kind resident"><b>우리 주민 가게</b><span>주민이 직접 운영</span></div><div class="kind family"><b>주민 가족 가게</b><span>주민 가족이 운영</span></div><div class="kind neighbor"><b>이웃가게</b><span>단지 가까운 생활 가게</span></div>';replaceText('우리 주민 가족 운영','주민 가족 가게');replaceText('우리 주민 운영','우리 주민 가게');replaceText('가까운 이웃가게','이웃가게');document.querySelectorAll('.shop-card').forEach(node=>{const label=node.querySelector('.shop-copy small');if(label)label.classList.add(/가족/.test(label.textContent)?'kind-family':/이웃가게/.test(label.textContent)?'kind-neighbor':'kind-resident')});document.querySelectorAll('.shop-card,.shop-link').forEach(node=>setRoute(node,route(2)));withText(/이웃가게 제보|수정 제보|신고/,route(25)+'?type=shop-report');withText(/내 가게 등록|가게 등록 문의/,route(25)+'?type=shop-register')}
    if(number===2){storeTools();storeReviews()}
    if(number===3){simpleBack('이웃가게',route(2));withText(/가게 보기/,route(2));withText(/돌아가기/,route(4))}
    if(number===4){simpleBack('시작',route(29));removeAll('.quick-strip');document.querySelectorAll('.lead-link').forEach(node=>setRoute(node,route(2)));withText(/주민혜택 전체보기|주민혜택 보기/,route(3));document.querySelectorAll('.news-item,.news-row').forEach(node=>{const text=clean(node.textContent);setRoute(node,/아파트/.test(text)?route(8):/단지온/.test(text)?route(6):route(10))});withText(/^전체보기/,route(5))}
    if(number===5){simpleBack('홈',route(4));removeAll('.permission-strip,.intro-copy');const latest={단지온공지:'단지온 이용 안내',아파트소식:'8월 입주민 간담회 안내',주민소식:'주민 재능나눔 모임',이웃대화:'오늘 분리수거장이 깨끗하게 정리되어 있네요.'};document.querySelectorAll('.channel').forEach(node=>{const title=[...Object.keys(latest)].find(key=>clean(node.textContent).includes(key));if(!title)return;node.className='channel danjion-channel';node.innerHTML='<span class="channel-kicker">'+({단지온공지:'운영 안내',아파트소식:'단지 소식',주민소식:'주민 제보',이웃대화:'주민 대화'}[title])+'</span><h2>'+title+'</h2><p class="danjion-latest">'+latest[title]+'</p><button class="channel-link" type="button"><span>보기</span><span>→</span></button>';setRoute(node.querySelector('button'),route({단지온공지:6,아파트소식:8,주민소식:10,이웃대화:12}[title]))})}
    if(number===6){removeAll('.filters,.pinned,.head-copy .eyebrow,.head-copy p');document.querySelectorAll('.notice-row,.notice').forEach(node=>setRoute(node,route(7)))}
    if(number===7){removeAll('#writing')}
    if(number===8){removeAll('.filters,.feature-photo');const feature=document.querySelector('.feature');if(feature)feature.classList.add('danjion-neutral-feature');const close=document.querySelector('.dialog-close');if(close){close.textContent='←';close.setAttribute('aria-label','소식 목록으로 돌아가기');close.title='뒤로가기'}}
    if(number===9){document.querySelectorAll('.opening,.support').forEach(node=>node.classList.add('danjion-paper-emphasis'))}
    if(number===10){removeAll('.intro-copy,.filters,.process,.steps');document.querySelectorAll('.feature,.story').forEach(node=>node.classList.add('danjion-neutral-story'));document.querySelectorAll('.news-row,.resident-row,.story-row,.story,.story-link').forEach(node=>setRoute(node,route(11)))}
    if(number===11){document.querySelectorAll('.quote').forEach(node=>node.classList.add('danjion-paper-emphasis'));withText(/다음 소식|목록/,route(10))}
    if(number===12){removeAll('.intro>p,.safety,.rail');document.querySelectorAll('.topic p').forEach(node=>node.remove());document.querySelectorAll('.post h3 a,.comment-more,.post-actions button').forEach(node=>{if(/댓글|모두 보기|안녕하세요|산책|분리|궁금|같이/.test(clean(node.textContent)))setRoute(node,route(13))});document.querySelectorAll('.write-type').forEach(node=>{const text=clean(node.textContent);setRoute(node,/가입인사/.test(text)?route(14):/단지이야기/.test(text)?route(15):/궁금/.test(text)?route(16):route(17))})}
    if(number===13){removeAll('.rail');withText(/메시지 보내기|1:1 메시지/,route(21));withText(/프로필/,route(22))}
    if(number>=14&&number<=17)writerPrefix(number);
    if(number===19){removeAll('.settings,.support-strip');withText(/메시지함|메시지 보기/,route(20));withText(/우리집|가족/,route(26));withText(/내가 쓴 글|내 댓글|공감한 글|나의 활동/,route(28));withText(/설정/,route(24));withText(/1:1 문의/,route(25));withText(/알림함|새 알림/,route(27));withText(/이웃 온기|단지레벨/,route(23))}
    if(number===20){removeAll('.mail-side,.mail-preview,.rail-card');document.querySelectorAll('.mail-row,.message-row,.ticket').forEach(node=>setRoute(node,route(21)))}
    if(number===21){removeAll('.rail,.mobile-reply,[aria-label="공유"]');document.querySelectorAll('.person,.sender').forEach(node=>setRoute(node,route(22)));withText(/메시지함/,route(20))}
    if(number===22){removeAll('.activity-button,.side,.visibility-list');withText(/1:1 메시지 보내기|메시지/,route(21))}
    if(number===23){removeAll('.route-note,.notice,.rules');replaceText('이웃 온기는 경쟁이 아닙니다.','좋은 이웃 활동이 차곡차곡 쌓입니다.');replaceText('건강한 참여를 다섯 단계로만 보여줍니다.','')}
    if(number===24){removeAll('.type-preview,.preview-copy');const subtitle=document.querySelector('.account-title span');if(subtitle)subtitle.remove();replaceText('자주 쓰는 설정을 찾기 쉽게 나누었습니다.','');withText(/1:1 문의/,route(25));withText(/우리집/,route(26));withText(/알림/,route(27))}
    if(number===25){removeAll('.help-card');inquiryMode();document.querySelectorAll('.history,.history-head').forEach(node=>node.classList.add('danjion-neutral-history'))}
    if(number===26){removeAll('.flow');document.querySelector('.house-card')?.classList.add('danjion-compact-house')}
    if(number===27){removeAll('.side');[/새 알림부터 보여드려요/].forEach(pattern=>removeTextBlocks(pattern,'p'));[[/단지온공지|이용 안내/,7],[/댓글|공감/,13],[/메시지/,21],[/문의 답변/,25],[/가족|우리집/,26],[/회장 인사/,9],[/알림 설정/,24]].forEach(([pattern,target])=>withText(pattern,route(target)))}
    if(number===28){document.querySelectorAll('.activity-layout>.side').forEach(node=>node.remove());const markFamilyRows=()=>document.querySelectorAll('.activity-row').forEach(row=>{if(!/바른 자동차정비/.test(clean(row.textContent)))return;row.dataset.type='주민 가족 가게';const label=row.querySelector('.activity-type b');if(label)label.textContent='주민 가족 가게'});const ensureFamilyFilter=()=>{const sub=document.querySelector('.subfilters');if(!sub||!/우리 주민 가게/.test(clean(sub.textContent))||/주민 가족 가게/.test(clean(sub.textContent)))return;const resident=[...sub.querySelectorAll('button')].find(node=>/우리 주민 가게/.test(clean(node.textContent)));if(!resident)return;const family=resident.cloneNode(true);family.textContent='주민 가족 가게';family.classList.remove('active');family.addEventListener('click',()=>{sub.querySelectorAll('button').forEach(item=>item.classList.remove('active'));family.classList.add('active');markFamilyRows();let visible=0;document.querySelectorAll('.activity-row').forEach(row=>{const isFamily=row.dataset.type==='주민 가족 가게';row.hidden=!isFamily;if(isFamily)visible++});const empty=document.querySelector('.empty');if(empty)empty.style.display=visible?'none':'grid'});resident.after(family);markFamilyRows()};ensureFamilyFilter();const sub=document.querySelector('.subfilters');if(sub)new MutationObserver(ensureFamilyFilter).observe(sub,{childList:true});document.querySelectorAll('[data-action="view"]').forEach(node=>setRoute(node,route(13)));document.querySelectorAll('[data-action="edit"]').forEach(node=>setRoute(node,route(15)))}
    if(number===29){document.querySelectorAll('.greeting-body').forEach(body=>{const resolve=body.querySelector('.resolve-line');if(resolve&&!body.querySelector('.delay-line')){const delay=document.createElement('p');delay.className='delay-line';delay.innerHTML='<strong>1년이 지난 동안 여러 일이 있었고, 그만큼 주민이 더 일찍 누릴 수 있었던 생활 편의와 혜택도 늦어졌습니다.</strong>';resolve.before(delay)}if(resolve)resolve.textContent='이제 더 미루지 않겠습니다.'});withText(/회장인사 전문/,route(9));withText(/^단지온 시작하기/,route(4))}
  };
  const init=()=>{const number=pageNumber()||Number(document.body.dataset.danjionPage)||0;document.body.dataset.danjionPage=String(number);normalizeCopy();rewriteLinks();controls().forEach(control=>{const label=clean(control.textContent);if(TOP[label]&&!control.matches('.active,[aria-current="page"]'))setRoute(control,route(TOP[label]))});document.querySelectorAll('.brand,.wordmark,[data-brand-home]').forEach(brand=>setRoute(brand,route(29)));addBack(number);pageRoutes(number);document.addEventListener('click',event=>{const locationControl=event.target.closest('[data-store-location]');if(locationControl){event.preventDefault();event.stopImmediatePropagation();const map=document.querySelector('#storeLocation,.map-card');if(map){let inline=document.querySelector('.danjion-inline-map');if(!inline){inline=document.createElement('section');inline.className='danjion-inline-map';inline.innerHTML='<div class="map-grid" aria-hidden="true"><i></i><i></i><i></i><i></i><strong>●</strong></div><div><b>로드힐 꽃작업실</b><span>광주 남구 방림동 · 정확한 주소는 예약 확정 후 안내</span></div>';map.after(inline)}inline.hidden=false;inline.scrollIntoView({behavior:'smooth',block:'center'})}return}const inquiryControl=event.target.closest('[data-store-inquiry]');if(inquiryControl){event.preventDefault();event.stopImmediatePropagation();openStoreInquiry();return}const backControl=event.target.closest('[data-back]');if(backControl){event.preventDefault();event.stopImmediatePropagation();location.href=backControl.dataset.fallback||route(4);return}const routeControl=event.target.closest('[data-route]');if(routeControl){const target=routeControl.dataset.route;if(target&&target.startsWith('#'))return;event.preventDefault();event.stopImmediatePropagation();location.href=target}},true)};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
